#!/usr/bin/env python3
"""After-WHOLE independent equation/frame/cache/ZIP/DXF check. No product imports."""
import hashlib,json,math,struct,sys,subprocess
from fractions import Fraction
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'native-cad-container'))
import archive_oracle as archive
from dxf_oracle import check as check_dxf
B=Fraction(1,20000000)
def require(ok,text):
    if not ok:raise ValueError(text)
def one(rows,text):require(len(rows)==1,'one '+text);return rows[0]
def F(v):
    require(type(v) in (int,float) and math.isfinite(v),'finite represented number');return Fraction.from_float(v) if type(v) is float else Fraction(v)
def canonical(v):return json.dumps(v,ensure_ascii=False,separators=(',',':'))
def raw(state,id):return one([r for r in state['capture']['native']['sketches'] if r['id']==id],'actual saved source')['source']
def parse(text):return archive.parse_json(text.encode('utf-8'))
def stable(s):
    s=json.loads(json.dumps(s));s['capture']['solids'].pop('revision',None);s['capture']['journal'].pop('revision',None)
    for key in ('host','frames','discovery','physical','units'):s[key].pop('revision',None)
    return s
def native_equal(a,b):
    for k in ('source','sketches','history','counters','expressions','presentation'):require(a['capture']['native'][k]==b['capture']['native'][k],'exact native '+k)
    require(a['materials']==b['materials'],'exact actual material metadata across sessions')
def settled(s):
    o=s['ownership'];r=o['resources'];require(not o['processing'] and not r['cleanupFailed'] and all(r[k]==0 for k in ('candidates','accepted','mounts')) and r['owners']==r['detached'] and not s['capture']['solids']['bodies'],'settled pure source ownership')
def wire_frame(state,featureId,faceId):
    row=one([r for r in state['frameBits'] if r['featureId']==featureId and r['faceId']==faceId],'actual public source frame IEEE binding');f=one([r for r in state['frames']['features'] if r['featureId']==featureId and r['faceId']==faceId],'actual public source frame')['frame'];result={}
    for k in ('origin','x','y','z'):
        require(len(row['frame'][k])==3 and len(f[k])==3,'complete frame basis');result[k]=[]
        for bits,value in zip(row['frame'][k],f[k]):
            require(isinstance(bits,str) and len(bits)==16 and all(c in '0123456789abcdef' for c in bits),'exact F64word');n=struct.unpack('>d',bytes.fromhex(bits))[0];require(math.isfinite(n) and n==value,'source bits equal numeric frame, signed zero retained separately');result[k].append(n)
    return result,row['frame']
def point(p,f):return [F(f['origin'][i])+F(f['x'][i])*F(p['x'])+F(f['y'][i])*F(p['y']) for i in (0,1)]
def nearpoint(p,w):require(sum(abs(F(p[k])-z) for k,z in zip(('x','y'),w))<=B,'exact affine rounding has <=50pm Euclidean error via L1')
def observation(row,initial):
    s=row['before'];require(row['before']==row['after'],'complete readonly state');settled(s);b=row['binding'];e=row['expected'];source=parse(raw(s,b['parent']['faceId']));objects={r['id']:r for r in source['objects']};base={r['id']:r for r in initial['objects']};require(len(objects)==len(source['objects']) and set(base)=={b['segmentId'],b['circleId'],b['alternativeId'],b['pointId']},'all actual original roots')
    for id in base:require({k:v for k,v in objects[id].items() if k!='data'}=={k:v for k,v in base[id].items() if k!='data'},'original root ID/type/role/stage preserved')
    require(objects[b['pointId']]['data']=={'x':7,'y':9} and objects[b['alternativeId']]['data']=={'a':{'x':2,'y':5},'b':{'x':12,'y':5}},'unrelated original geometry exact');line=objects[b['segmentId']];circle=objects[b['circleId']];require(line['data']=={'a':{'x':0,'y':0},'b':dict(zip(('x','y'),e['endpoint']))} and circle['data']=={'c':{'x':20,'y':20},'r':e['radius']},'declared original source geometry, no copy-over')
    h=s['capture']['native']['history'];parent=one([r for r in h if int(r['params']['featureId'])==b['parent']['featureId']],'genuine source producer');require(parent['type']=='SOURCE_FRAME_V1' and parent['params']['parent'] is None,'independent real source frame');f,words=wire_frame(s,b['parent']['featureId'],b['parent']['faceId']);placement=parent['params']['placement'];require(placement['kind'] in ('basis','rigid'),'ordinary declared placement');require(e['angle'] in (0,45),'frozen ordinary rotation family');t=math.radians(e['angle']);c=math.cos(t);sn=math.sin(t);nominal={'origin':[e['translation'][0],e['translation'][1],e['depth']+e['translation'][2]],'x':[c,sn,0],'y':[-sn,c,0],'z':[0,0,1]}
    for key in nominal:
        for a,z in zip(f[key],nominal[key]):require(abs(F(a)-F(z))<=(B if key=='origin' else Fraction(1,10**12)),'actual frame follows declared source placement')
    savedframe=source['metadata']['boundaryFrame'];require(all(abs(F(f[k][i])-F(savedframe[k][i]))<=Fraction(1,10**9) for k in f for i in range(3)),'original source cache frame admission unchanged');require(source['boundary']==initial['boundary'] and all(not r for r in source['boundary'].values()),'original source remains boundary-free')
    constraints=source['stages'][0]['constraints'];require(len(source['stages'])==1 and len(constraints)==(0 if e['radius']==5 else 1),'complete authored constraint census')
    for actual,cold in zip(constraints,row['inspection']['constraints']):
        require(actual['typeId']=='RadiusLength' and actual['objects']==[b['circleId']] and actual['constants']=={'length':str(e['radius'])},'genuine original RadiusLength equation');require(actual['admission']['state'] in ('accepted','redundant'),'solver-derived admission');require(all(actual[k]==cold[k] for k in ('typeId','objects','constants','admission','stage')),'fresh cold/source authored row identity')
    require(len(row['inspection']['constraints'])==len(constraints),'full fresh equation census')
    # Every cold original child is tied to its actual public owner and saved point.
    for id,o in objects.items():
        if o['type'] not in ('Point','Segment','Circle'):raise ValueError('unexpected source primitive')
        ps=[o['data']] if o['type']=='Point' else [o['data']['c']] if o['type']=='Circle' else [o['data']['a'],o['data']['b']];cold=[r for r in row['inspection']['points'] if r['parentId']==id];require(len(cold)==len(ps),'complete original point ownership');used=set()
        for cp in cold:
            at=one([i for i,p in enumerate(ps) if all(abs(F(cp[k])-F(p[k]))<=B for k in ('x','y'))],'cold point within existing per-coordinate50pm bound');require(at not in used,'distinct actual child occurrences');used.add(at)
    generated=row.get('generated');gens=source['stages'][0]['generators'];require(len(gens)==(1 if generated else 0) and len(objects)==len(base)+(1 if generated else 0),'full generator/output census')
    if generated:
        g=gens[0];require(g['typeId']=='Offset' and g['generatedObjects']==[generated['outputId']] and g['params']=={'objects':[b['segmentId']],'distance':2,'side':'left'},'genuine generated-control original intent');out=objects[generated['outputId']];require(out['type']=='Segment','true generated Segment');a,z=line['data']['a'],line['data']['b'];dx=F(z['x'])-F(a['x']);dy=F(z['y'])-F(a['y']);L=math.hypot(float(dx),float(dy))
        for end in ('a','b'):
            p=line['data'][end];require(math.hypot(out['data'][end]['x']-(p['x']-float(dy)*2/L),out['data'][end]['y']-(p['y']+float(dx)*2/L))<=5e-8,'actual finite generated-control geometry')
    foreign=row.get('foreign')
    if foreign:
        other=parse(raw(s,foreign['faceId']));require(len(other['objects'])==1 and other['objects'][0]['id']==foreign['objectId'] and other['objects'][0]['type']=='Segment' and other['objects'][0]['data']=={'a':{'x':1,'y':2},'b':{'x':3,'y':4}},'actual retained foreign source, no invented foreign ID')
    require(s['capture']['native']['expressions']=='','literal source family, no parameter substitution');target_id=b['projection']['faceId'];entries=[r for r in h if r['type']=='SOURCE_PROJECTION_V1'];require(len(entries)==(1 if e['present'] else 0),'actual projection history cardinality')
    if not e['present']:require(row['read'] is None and row['display'] is None and all(r['id']!=target_id for r in s['capture']['native']['sketches']),'Undo/removal actually absent');return
    entry=entries[0];p=entry['params'];require(p['featureId']==b['projection']['featureId'] and p['source']['featureId']==b['parent']['featureId'] and p['source']['faceId']==b['parent']['faceId'] and p['target']=={'plane':'XY','depth':0},'actual authored source/target authority');ids=[b['alternativeId'] if e['repaired'] else b['segmentId'],b['circleId']];require(p['source']['objectIds']==ids and [r['sourceObjectId'] for r in p['outputs']]==ids and [r['referenceId'] for r in p['outputs']]==[r['referenceId'] for r in b['projection']['outputs']],'stable reference IDs and explicit changed source root')
    cache_text=raw(s,target_id);cache=parse(cache_text);read=row['read'];require(cache['objects']==cache['dimensions']==cache['labels']==[] and len(cache['stages'])==1 and cache['stages'][0]['constraints']==cache['stages'][0]['generators']==[],'reference cache has no second authored geometry');require(cache['metadata']['boundaryFrame']=={'origin':[0,0,0],'x':[1,0,0],'y':[0,1,0],'z':[0,0,1]} and read['frame']==cache['metadata']['boundaryFrame'],'worldXYz0 target');source_text=raw(s,b['parent']['faceId']);digest=hashlib.sha256(source_text.encode()).hexdigest();require(read['sourceSha256']==cache['metadata']['sourceProjection']['sourceSha256']==digest,'actual raw original source SHA256')
    parts=['source-projection-v1',source_text,canonical(p)]+[word for key in ('origin','x','y','z') for word in words[key]];binding=hashlib.sha256(''.join(str(len(x.encode()))+':'+x for x in parts).encode()).hexdigest();require(binding==read['bindingSha256']==cache['metadata']['sourceProjection']['bindingSha256'],'independent length-delimited intent/frame IEEE/source hash')
    require(len(read['references'])==2 and len(cache['boundary']['lines'])==len(cache['boundary']['circles'])==1 and not cache['boundary']['arcs'] and not cache['boundary']['nurbses'],'complete actual two-reference geometry');require(len(row['display']['objects'])==2 and row['display']['contours']==0,'real visible construction references excluded from profile')
    for binding in p['outputs']:
        original=objects[binding['sourceObjectId']];r=one([r for r in read['references'] if r['referenceId']==binding['referenceId']],'actual public reference');require(r['sourceObjectId']==original['id'] and r['members'][0]==original['id'] and len(r['members'])==(3 if original['type']=='Segment' else 2) and len(set(r['members']))==len(r['members']),'actual original descendant IDs, never parsed');require(r['kind']==original['type'],'original source kind retained');require(set(r['members'][1:])=={cp['id'] for cp in row['inspection']['points'] if cp['parentId']==original['id']},'independent actual descendant ID membership');geometry=r['geometry'];stored=one([v for v in cache['boundary']['lines' if r['kind']=='Segment' else 'circles'] if v['id']==binding['referenceId']],'actual cached reference');require({k:v for k,v in stored.items() if k!='id'}==geometry,'same protected read/cache geometry');display=one([v for v in row['display']['objects'] if v['kind']==r['kind']],'actual adopted display');require({k:v for k,v in display.items() if k not in ('id','kind')}==geometry,'actual visible model, not empty cached proxy')
        if r['kind']=='Segment':
            for key in ('a','b'):nearpoint(geometry[key],point(original['data'][key],f))
            require(math.hypot(geometry['b']['x']-geometry['a']['x'],geometry['b']['y']-geometry['a']['y'])>1e-9,'finite projected Segment')
        else:
            require(f['x'][2]==f['y'][2]==0 and geometry['r']==original['data']['r'],'genuine parallel-plane Circle, no ellipse substitution');w=point(original['data']['c'],f);error=sum(abs(F(geometry['c'][k])-z) for k,z in zip(('x','y'),w));u=[F(n) for n in f['x'][:2]];v=[F(n) for n in f['y'][:2]];dot=lambda a,b:sum(x*y for x,y in zip(a,b));delta=abs(dot(u,u)-1)+abs(dot(v,v)-1)+2*abs(dot(u,v));require(delta<1 and error+F(geometry['r'])*delta<=B,'independent full-circle Euclidean error bound')
PHASES=['Initial associative projection','Creation Undo','Creation Redo','Parent depth15 preserves XY geometry','Depth Undo','Depth Redo','General in-plane45 rotation plus translation','Rotation Undo','Rotation Redo','Fresh Open rotated source','Original source endpoint12,3','Endpoint Undo','Endpoint Redo','Original RadiusLength7','Radius Undo','Radius Redo','Explicit same-source repair retains referenceId','Repair Undo','Repair Redo','Explicit latest projection removal','Removal Undo','Removal Redo','Removal recovery Undo','Inches preserve physical source','Fresh Open repaired source','Fresh Open original endpoint reedit after explicit repair','PostOpen endpoint Undo','PostOpen endpoint Redo','Fresh Open radius9 propagates','Millimeter display restores presentation only','Third fresh Open retains both real associations','Third Open genuine radius10 reedit','ThirdOpen radius Undo','ThirdOpen radius Redo','Before real generated-source control','Actual Offset output is discoverable but not projectable','Generated control Undo','Genuine independent foreign source retained','Before source-proven numerical uncertainty control','Large actual Circle remains valid in genuine45deg frame','Uncertainty control recovery Undo']
REFUSALS={'Stale projection discovery revision':'STALE_SOURCE','Unknown source root':'PROJECTION_REFERENCE_MISSING','Point root is not a curve':'PROJECTION_REFERENCE_TYPE','Incompatible repair':'PROJECTION_REFERENCE_TYPE','Referenced root deletion':'PROJECTION_DEPENDENCY','Child endpoint is not a source root':'PROJECTION_REFERENCE_MISSING','Projected source is not independently editable':None,'Exact projected Segment collapse':'PROJECTION_COLLAPSED_SEGMENT','Tilted Circle parent refuses ellipse substitution':'PROJECTION_CIRCLE_FRAME_UNQUALIFIED','Generated source root cannot be reauthored':'PROJECTION_REFERENCE_GENERATED','Actual foreign source root refuses':'PROJECTION_REFERENCE_MISSING','Valid near-orthogonal represented frame cannot prove50pm Circle':'PROJECTION_CIRCLE_FRAME_UNQUALIFIED'}
def run(directory):
    directory=Path(directory);r=archive.parse_json((directory/'receipt.json').read_bytes());require(r['status']=='PASS' and not r['privateAuthoring'] and not r['sourceSeeds'] and not r['fakeReplies'],'actual whole terminalPASS');require(r['physicalBudgetMillimeters']==5e-8 and r['sourceUnchanged'] and r['ownedContextsRetired'] and r['remainingOwnedTargets']==[] and r['pendingWrite'] is None and r['sharedBrowserDisconnectedOnly'],'all source/context/write custody settled')
    seen=set();require(1<=len(r['sourceRoster'])<=128,'bounded frozen producer roster')
    for pin in r['sourceRoster']:
        key=(pin['repo'],pin['path']);require(key not in seen,'unique actual producer association');seen.add(key);data=(directory/pin['file']).read_bytes();require(len(data)==pin['bytes'] and hashlib.sha256(data).hexdigest()==pin['sha256'] and hashlib.sha1(('blob '+str(len(data))+'\0').encode()+data).hexdigest()==pin['blob'],'actual retained source bytes and Git blob');require(len(pin['commit'])==40 and all(c in '0123456789abcdef' for c in pin['commit']),'actual full source commit');member=subprocess.run(['git','-C',pin['repo'],'rev-parse',pin['commit']+':'+pin['path']],capture_output=True,check=True).stdout.decode().strip();blob=subprocess.run(['git','-C',pin['repo'],'cat-file','blob',pin['blob']],capture_output=True,check=True).stdout;require(member==pin['blob'] and blob==data,'independent actual commit/path/blob source association')
    require(any(p.endswith('/strict-join/oracle.mjs') for _,p in seen) and any(p=='test/native-cad-container/archive_oracle.py' for _,p in seen),'transitive independent helper custody');require([x['label'] for x in r['observations']]==PHASES,'EXACT whole lifecycle, not count-only')
    b=r['binding'];initial=parse(raw(r['preCreation'],b['parent']['faceId']));require(initial['stages'][0]['constraints']==initial['stages'][0]['generators']==[],'genuine initial source, no seeded row')
    expected={'angle':0,'depth':5,'translation':[0,0,0],'endpoint':[10,0],'radius':5,'repaired':False,'present':True}
    changes={1:{'present':False},2:{'present':True},3:{'depth':15},4:{'depth':5},5:{'depth':15},6:{'angle':45,'translation':[3,-4,2]},7:{'angle':0,'translation':[0,0,0]},8:{'angle':45,'translation':[3,-4,2]},10:{'endpoint':[12,3]},11:{'endpoint':[10,0]},12:{'endpoint':[12,3]},13:{'radius':7},14:{'radius':5},15:{'radius':7},16:{'repaired':True},17:{'repaired':False},18:{'repaired':True},19:{'present':False},20:{'present':True},21:{'present':False},22:{'present':True},25:{'endpoint':[14,4]},26:{'endpoint':[12,3]},27:{'endpoint':[14,4]},28:{'radius':9},31:{'radius':10},32:{'radius':9},33:{'radius':10},39:{'radius':1000000},40:{'radius':10}}
    for i,row in enumerate(r['observations']):
        expected.update(changes.get(i,{}));require(row['expected']==expected,'exact frozen case transition '+row['label']);units='inch' if 23<=i<=28 else 'millimeter';require(row['before']['units']['lengthUnit']==units and row['before']['capture']['native']['presentation']==({'version':1,'lengthUnit':'inch'} if units=='inch' else None),'actual presentation preserves physical source');observation(row,initial)

    by={x['label']:x for x in r['observations']};require(by['General in-plane45 rotation plus translation']['expected']['angle']==45,'general rotation not replaced with signed permutation');require(by['Original source endpoint12,3']['expected']['endpoint']==[12,3] and by['Original RadiusLength7']['expected']['radius']==7 and by['Fresh Open radius9 propagates']['expected']['radius']==9 and by['Third Open genuine radius10 reedit']['expected']['radius']==10,'all prescribed independent source re-edits')
    travels=[('Creation Undo','undo'),('Creation Redo','redo'),('Depth Undo','undo'),('Depth Redo','redo'),('Rotation Undo','undo'),('Rotation Redo','redo'),('Endpoint Undo','undo'),('Endpoint Redo','redo'),('Radius Undo','undo'),('Radius Redo','redo'),('Repair Undo','undo'),('Repair Redo','redo'),('Removal Undo','undo'),('Removal Redo','redo'),('Removal recovery Undo','undo'),('PostOpen endpoint Undo','undo'),('PostOpen endpoint Redo','redo'),('ThirdOpen radius Undo','undo'),('ThirdOpen radius Redo','redo'),('Generated control Undo','undo'),('Uncertainty control recovery Undo','undo')]
    require([(t['label'],t['direction']) for t in r['travels']]==travels,'all21 actual original-request travel operations')
    for t in r['travels']:require(t['after']==by[t['label']]['before'] and t['before']['capture']['native']['counters']==t['after']['capture']['native']['counters'],'travel actual source/counter observation, no new ID allocation')
    require([c['args']['direction'] for c in r['commands'] if c['command']=='travel-authored-edit' and 'result' in c]==[direction for _,direction in travels],'actual registered travel trace')

    created=by['Initial associative projection']['before'];pre=r['preCreation']['capture']['native']['counters'];post=created['capture']['native']['counters'];require(post['featureId']==pre['featureId']+1 and {k:v for k,v in pre.items() if k!='featureId'}=={k:v for k,v in post.items() if k!='featureId'},'one genuine allocated feature, other counters unchanged');undone=by['Creation Undo']['before'];require(undone['capture']['native']['history']==r['preCreation']['capture']['native']['history'] and undone['capture']['native']['sketches']==r['preCreation']['capture']['native']['sketches'] and undone['capture']['native']['counters']==created['capture']['native']['counters'],'immediate creation Undo actualsource/H/highwater');native_equal(by['Creation Redo']['before'],created)
    require({x['label']:x['error']['code'] for x in r['refusals']}==REFUSALS and len(r['refusals'])==len(REFUSALS),'exact finite failure layers')
    for x in r['refusals']:require(x['code']==REFUSALS[x['label']] and not x['error']['committed'] and not x['error']['possiblyCommitted'] and stable(x['before'])==stable(x['after']),'last-good state exact after refusal');settled(x['after'])
    gd=r['generatedDiscovery'];grow=one([v for v in gd['result']['objects'] if v['id']==gd['binding']['outputId']],'public generated source row');require(not grow['canProject'] and grow['reason']['code']=='PROJECTION_REFERENCE_GENERATED','actual public generated admission distinction')
    require(one([x for x in r['refusals'] if x['label']=='Projected source is not independently editable'],'readonly refusal')['error']['name']=='AbortError','actual unavailable target mutation layer')
    uncertainty=one([x for x in r['refusals'] if x['label']=='Valid near-orthogonal represented frame cannot prove50pm Circle'],'numeric uncertainty refusal');require(one([o for o in parse(raw(uncertainty['before'],b['parent']['faceId']))['objects'] if o['id']==b['circleId']],'actual uncertainty Circle')['data']['r']==1000000,'genuine million-mm radius before uncertainty');x=F(1+4e-13);require(abs(x*x-1)<=Fraction(1,10**12) and abs(x-1)<=Fraction(1,10**12) and 1000000*abs(x*x-1)>B,'source-frame valid but exact Circle preservation exceeds50pm')
    no=one([x for x in r['rows'] if x['label']=='Same binding no-op preserves exact state'],'actual no-op');require(not no['result']['changed'] and not no['result']['committed'] and no['before']==no['after'],'same binding no-op exact')
    require([s['label'] for s in r['saves']]==['rotated-source','repaired-inch','reopened-radius9'],'three real saved cycles');archives=[]
    for s,label in zip(r['saves'],['Fresh Open rotated source','Fresh Open repaired source','Third fresh Open retains both real associations']):
        a=archive.read_archive(directory/s['file']);n=s['before']['capture']['native'];m=a['envelope']['project']['model'];require(a['sha256']==s['sha256'] and a['bytes']==s['bytes'] and s['result']['committed'],'browser/server actual native bytes');require(m['history']==n['history'] and m['counters']==n['counters'] and m['expressions']==n['expressions'] and a['rawSketches']=={v['id']:v['source'] for v in n['sketches']} and a['envelope'].get('presentation')==n['presentation'],'exact .cad source/reference/cache/H/counter/presentation');native_equal(by[label]['before'],s['before']);require(not by[label]['before']['capture']['journal']['canUndo'] and not by[label]['before']['capture']['journal']['canRedo'],'fresh native session J reset');require(s['before']['capture']==s['after']['capture'],'Save readonly accepted state');archives.append({'file':s['file'],'sha256':a['sha256'],'designRevision':a['manifest']['designRevision']})
    require([e['label'] for e in r['exports']]==['rotated','repaired-inch','reopened-radius9'],'full three current DXF cases');exports=[]
    for e in r['exports']:
        data=(directory/e['file']).read_bytes();require(len(data)==e['bytes'] and hashlib.sha256(data).hexdigest()==e['sha256'] and e['before']==e['after'],'real export server equality/read-only');row=r['observations'][e['observationIndex']];require(row['before']['capture']==e['before']['capture'],'current accepted definition/source association');exports.append({'file':e['file'],**check_dxf(data,row['read'])})
    return {'status':'PASS','scope':r['scope'],'observations':len(r['observations']),'travels':len(r['travels']),'refusals':len(r['refusals']),'archives':archives,'exports':exports}
if __name__=='__main__':print(json.dumps(run(sys.argv[1]),indent=2))
